class Readiness { const Readiness({required this.bluetooth,required this.helmet,required this.location,required this.sms,required this.contacts}); final bool bluetooth,helmet,location,sms,contacts; bool get ready=>bluetooth&&helmet&&location&&sms&&contacts; List<String> get reasons=>[if(!bluetooth)'Bluetooth unavailable or permission missing',if(!helmet)'Helmet disconnected',if(!location)'Location unavailable',if(!sms)'SMS permission unavailable',if(!contacts)'No enabled emergency contacts']; }
